sys_script_include.script:
class DHAPIConfig {
  /**
   * @typedef {Object}
   * Map of Nexthink headers and Metric record field names.
   */
  static DEVICEMETRICMAP = {
    "device.name":"device_name",
    "device.collector.uid": "uid",
    "device.average_boot_duration_7d.rating":"average_boot_duration_7d",
    "device.boot.days_since_last_full_boot.rating":"days_since_last_full_boot",
    "device.average_time_until_desktop_is_ready_7d.rating":"average_time_until_desktop_is_ready_7d",
    "device.average_time_until_desktop_is_visible_7d.rating":"average_time_until_desktop_is_visible_7d",
    "device.average_wifi_signal_strength_24h.rating":"average_wifi_signal_strength_24h",
    "device.average_cpu_usage_24h.rating": "average_cpu_usage_24h",
    "device.average_memory_usage_24h.rating": "average_memory_usage_24h",
    "device.last_system_drive_free_space.rating": "last_system_drive_free_space",
    "device.number_of_hard_resets_7d.rating": "number_of_hard_resets_7d",
    "device.number_of_system_crashes_7d.rating": "number_of_system_crashes_7d"
  };

  static NXT_DEXSCORESQRYID = "#service_now_scorecard_dex_score_per_day";
  static NXT_DEVICEMETRICQRYID = "#service_now_scorecard_device_metrics";

  /**
   * Function which will return the UPN required by Nexthink, this can be
   * modified if required to identify the user UPN in Nexthink.
   * @param {string} field - Name of field on sys_user record
   * @returns string
   */
  static NXT_UPN(field) {

    field = field || 'email'
    const user = new global.GlideQuery('sys_user')
    .get(gs.getUserID(), [field])
    .orElse(null);

    if(!user || !user[field]) throw new Error(`User found does not have a value for: ${field}`)

    return user[field]
  }

  /**
   * @typedef {Array<string>} - Fields the widget needs for Device Metrics
   *
   */
  static CACHEPAYLOAD = ["overall_score", "actions", "ra_run_today","asset.sys_id", "asset.model$DISPLAY"];

  /**
   * Getter function to ensure the widget receives the correct fields from the API/Cache
   */
  static get cache_fields() {
    var maps_fields = Object.values(this.DEVICEMETRICMAP);

    return maps_fields.concat(this.CACHEPAYLOAD);
  }

  static DEXSCOREMAP = {
    start_time: "date",
    score: "dex_score",
  };

  static get metric_map() {
    return this.DEVICEMETRICMAP;
  }

  static get dex_map() {
    return this.DEXSCOREMAP;
  }

}
